/** Pre-generated by `scripts/generate-contours.mjs` (fixed seed); served from `public/`. */
export const CONTOUR_TEXTURE_URL = `${import.meta.env.BASE_URL}textures/contours.svg`

/**
 * Contour_Background (Requirement 15.7): the page-level topographic texture.
 * The static SVG is used as a mask over a token colour, so the line colour
 * stays in the token layer; the layer sits at `--line-contour-opacity` (6%)
 * and never takes pointer events.
 */
export function ContourBackground() {
  const mask = `url(${CONTOUR_TEXTURE_URL})`
  return (
    <div
      aria-hidden="true"
      data-part="contours"
      className="pointer-events-none fixed inset-0 -z-10"
      style={{
        pointerEvents: 'none',
        opacity: 'var(--line-contour-opacity)',
        backgroundColor: 'var(--contour-stroke)',
        maskImage: mask,
        WebkitMaskImage: mask,
        maskSize: 'cover',
        WebkitMaskSize: 'cover',
        maskPosition: 'center',
        WebkitMaskPosition: 'center',
        maskRepeat: 'no-repeat',
        WebkitMaskRepeat: 'no-repeat',
      }}
    />
  )
}
